#include <zephyr/drivers/can.h>
#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define CAN_NODE DT_CHOSEN(zephyr_canbus)

#if DT_NODE_HAS_PROP(CAN_NODE, phy)
#define CAN_PHY_NODE DT_PHANDLE(CAN_NODE, phy)
#endif

#if DT_NODE_HAS_STATUS(CAN_NODE, okay)
static const struct device *const can_dev = DEVICE_DT_GET(CAN_NODE);
#ifdef CAN_PHY_NODE
static const struct device *const can_phy_dev = DEVICE_DT_GET(CAN_PHY_NODE);
#endif /* CAN_PHY_NODE */
#else  /* DT_NODE_HAS_STATUS(CAN_NODE, okay) */
/* To avoid build errors if the CAN device is not available. */
static const struct device *const can_dev;
#ifdef CAN_PHY_NODE
static const struct device *const can_phy_dev;
#endif /* CAN_PHY_NODE */
#endif /* DT_NODE_HAS_STATUS(CAN_NODE, okay) */

#define ztest_skip_if_no_device()                                                                  \
	do {                                                                                       \
		if (can_dev == NULL || !device_is_ready(can_dev)) {                                \
			ztest_test_skip();                                                         \
		}                                                                                  \
		IF_ENABLED(DT_NODE_HAS_PROP(CAN_NODE, phy), ({                                     \
			if (can_phy_dev == NULL || !device_is_ready(can_phy_dev)) {                \
				ztest_test_skip();                                                 \
			}                                                                          \
		}));                                                                               \
	} while (false)

static void *can_api_setup(void)
{
	ztest_skip_if_no_device();

#ifdef CONFIG_USERSPACE
	k_object_access_grant(can_dev, k_current_get());
#endif /* CONFIG_USERSPACE */

	return NULL;
}

static void can_api_before(void *data)
{
	ARG_UNUSED(data);
	int err;

	err = can_stop(can_dev);
	zassert_ok(err, "failed to stop CAN controller");
}

ZTEST(can_api, test_bitrate_limits)
{
	uint32_t min_bitrate;
	uint32_t max_bitrate;

	ztest_skip_if_no_device();

	min_bitrate = can_get_bitrate_min(can_dev);
	max_bitrate = can_get_bitrate_max(can_dev);

	zassert_not_equal(0, max_bitrate, "max bitrate cannot be 0");
	zassert_true(min_bitrate <= max_bitrate, "min bitrate (%u) > max bitrate (%u)",
		     min_bitrate, max_bitrate);
}

ZTEST(can_api, test_classic_get_capabilities)
{
	can_mode_t caps;
	int err;

	ztest_skip_if_no_device();

	err = can_get_capabilities(can_dev, &caps);
	zassert_ok(err, "failed to get CAN capabilities");

	if ((caps & CAN_MODE_FD) != 0) {
		ztest_test_skip();
	}

	zassert_true((caps & CAN_MODE_NORMAL), "normal mode not supported");
}

ZTEST(can_api, test_filters_added_while_stopped)
{
	const struct can_filter filter = {
		.id = 0x123,
		.mask = CAN_STD_ID_MASK,
		.flags = CAN_FILTER_IDE
	};
	int filter_id;

	ztest_skip_if_no_device();

	filter_id = can_add_rx_filter(can_dev, NULL, NULL, &filter);
	zassert_not_equal(filter_id, -ENOSPC, "no free filter left");
	zassert_true(filter_id >= 0, "failed to add rx filter, err: %d", filter_id);

	can_remove_rx_filter(can_dev, filter_id);
}

ZTEST(can_api, test_filters_preserved_through_bitrate_change)
{
	const struct can_filter filter = {
		.id = 0x456,
		.mask = CAN_STD_ID_MASK,
		.flags = CAN_FILTER_IDE
	};
	int filter_id;
	int err;

	ztest_skip_if_no_device();

	filter_id = can_add_rx_filter(can_dev, NULL, NULL, &filter);
	zassert_true(filter_id >= 0, "failed to add rx filter, err: %d", filter_id);

	err = can_set_bitrate(can_dev, 125000);
	zassert_ok(err, "failed to set bitrate");

	can_remove_rx_filter(can_dev, filter_id);
}

ZTEST(can_api, test_filters_preserved_through_mode_change)
{
	const struct can_filter filter = {
		.id = 0x789,
		.mask = CAN_STD_ID_MASK,
		.flags = CAN_FILTER_IDE
	};
	int filter_id;
	int err;

	ztest_skip_if_no_device();

	filter_id = can_add_rx_filter(can_dev, NULL, NULL, &filter);
	zassert_true(filter_id >= 0, "failed to add rx filter, err: %d", filter_id);

	err = can_set_mode(can_dev, CAN_MODE_LOOPBACK);
	zassert_ok(err, "failed to set mode");

	can_remove_rx_filter(can_dev, filter_id);
}

ZTEST(can_api, test_get_core_clock)
{
	uint32_t core_clock;
	int err;

	ztest_skip_if_no_device();

	err = can_get_core_clock(can_dev, &core_clock);
	if (err == -ENOSYS) {
		ztest_test_skip();
	}

	zassert_ok(err, "failed to get CAN core clock");
	zassert_positive(core_clock, "CAN core clock must be positive");
}

ZTEST(can_api, test_get_state)
{
	enum can_state state;
	struct can_bus_err_cnt err_cnt;
	int err;

	ztest_skip_if_no_device();

	err = can_get_state(can_dev, &state, &err_cnt);
	zassert_ok(err, "failed to get CAN controller state");
	zassert_equal(state, CAN_STATE_STOPPED, "CAN controller should be in stopped state");
}

ZTEST_SUITE(can_api, NULL, can_api_setup, can_api_before, NULL, NULL);
